def match(orders):
    buy_book = []  # list of (price, arrival_time, id, qty) - sorted by price desc, then arrival_time asc
    sell_book = []  # list of (price, arrival_time, id, qty) - sorted by price asc, then arrival_time asc
    trades = []
    order_map = {}  # id -> (side, index_in_book) to track order positions
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, book_idx = order_map[order_id]
                if book_idx is not None:  # order is still resting
                    if side == 'buy':
                        buy_book[book_idx] = None
                    else:
                        sell_book[book_idx] = None
                    del order_map[order_id]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = None if order_type == 'market' else order[3]

            if side == 'buy':
                # Match against sell book
                while qty > 0 and sell_book:
                    # Remove None entries from front
                    while sell_book and sell_book[0] is None:
                        sell_book.pop(0)

                    if not sell_book:
                        break

                    sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]

                    # Check if we can match
                    if order_type == 'market' or price >= sell_price:
                        match_qty = min(qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, match_qty])
                        qty -= match_qty

                        if match_qty == sell_qty:
                            sell_book.pop(0)
                            if sell_id in order_map:
                                del order_map[sell_id]
                        else:
                            sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - match_qty)
                    else:
                        break

                # Rest remaining qty if limit order
                if qty > 0 and order_type == 'limit':
                    book_idx = len(buy_book)
                    buy_book.append((price, arrival_time, order_id, qty))
                    order_map[order_id] = ('buy', book_idx)
                    # Re-sort buy book by price desc, then arrival asc
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    # Update order_map indices
                    for i, entry in enumerate(buy_book):
                        if entry is not None:
                            order_map[entry[2]] = ('buy', i)

            else:  # side == 'sell'
                # Match against buy book
                while qty > 0 and buy_book:
                    # Remove None entries from front
                    while buy_book and buy_book[0] is None:
                        buy_book.pop(0)

                    if not buy_book:
                        break

                    buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]

                    # Check if we can match
                    if order_type == 'market' or price <= buy_price:
                        match_qty = min(qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, match_qty])
                        qty -= match_qty

                        if match_qty == buy_qty:
                            buy_book.pop(0)
                            if buy_id in order_map:
                                del order_map[buy_id]
                        else:
                            buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - match_qty)
                    else:
                        break

                # Rest remaining qty if limit order
                if qty > 0 and order_type == 'limit':
                    book_idx = len(sell_book)
                    sell_book.append((price, arrival_time, order_id, qty))
                    order_map[order_id] = ('sell', book_idx)
                    # Re-sort sell book by price asc, then arrival asc
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    # Update order_map indices
                    for i, entry in enumerate(sell_book):
                        if entry is not None:
                            order_map[entry[2]] = ('sell', i)

    return trades

